// Program.cs mit Top-Level-Statements
Console.WriteLine($"Anzahl: {args.Length}");
for (int i = 0; i < args.Length; i++)
    Console.WriteLine(
        $"args[{i}] = {args[i]}");

// Aufruf: notenrechner noten.csv 5
// Ausgabe:
// Anzahl: 2
// args[0] = noten.csv
// args[1] = 5

var alle =
    Environment.GetCommandLineArgs();

Console.WriteLine(args.Length);
Console.WriteLine(alle.Length);
Console.WriteLine(alle[1] == args[0]);

// Aufruf: notenrechner noten.csv
// Ausgabe:
// 1
// 2
// True

using System.Text.RegularExpressions;

int stellen = 1;
var noten = new List<int>();

foreach (string a in args)
{
    var m = Regex.Match(a,
        @"^--stellen=(\d)$");
    if (m.Success)
        stellen = int.Parse(
            m.Groups[1].Value);
    else if (Regex.IsMatch(a, "^[1-5]$"))
        noten.Add(int.Parse(a));
    else
    {
        Console.WriteLine($"Ungültig: {a}");
        return 1;
    }
}

if (noten.Count == 0)
{
    Console.WriteLine("Keine Noten!");
    return 1;
}
double s = noten.Average();
Console.WriteLine(Math.Round(s, stellen));
return 0;
// Aufruf: schnitt 1 2 2 --stellen=2
// Ausgabe: 1,67
